head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > clearInterval]<br/>$p.setInterval() 메소드로 등록한 반복 타이머를 제거합니다.",
    "validation" : [
        "key(필수) 파라미터로 제거할 반복 타이머의 키값을 설정할 수 있어야 합니다.",
        "key 파라미터에 Function 타입이 전달되면 함수를 문자열로 변환한 뒤 앞 30 자를 키값으로 사용해야 합니다.",
        "force(선택) 를 true 로 설정 시 등록된 함수를 한 번 실행한 뒤 타이머를 제거해야 합니다.",
        "force(선택) 를 false 로 설정 시 등록된 함수를 실행하지 않고 타이머를 제거해야 합니다.",
        "force(선택) 생략 시 기본값 false 로 동작해야 합니다.",
        "존재하지 않는 키값을 전달하면 아무 동작도 하지 않아야 합니다.",
    ]
}

scwin.count = 0;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.timerFunc = function () {
    scwin.count++;
    wf_body_bottom.getObj("scwin").setReturnValue("타이머 실행 횟수 : " + scwin.count);
}



scwin.btn_setInterval_onclick = function () {
    var key = par_key.getValue();

    scwin.count = 0;
    if (key === "function") {
        $p.setInterval(scwin.timerFunc, {delay:3000});
        wf_body_bottom.getObj("scwin").setReturnValue("setInterval 등록 완료 (key: Function, 3000ms)");
    } else {
        $p.setInterval(scwin.timerFunc, {key:key, delay:3000});
        wf_body_bottom.getObj("scwin").setReturnValue("setInterval 등록 완료 (key: '" + key + "', 3000ms)");
    }
}



scwin.btn_clearInterval_onclick = function () {
    var key = par_key.getValue();
    var force = par_force.getValue();
    var beforeCount = scwin.count;

    if (force === "omit") {
        $p.clearInterval(key);
    } else if (key === "function") {
        $p.clearInterval(scwin.timerFunc, force === "true");
    } else {
        $p.clearInterval(key, force === "true");
    }

    var afterCount = scwin.count;
    wf_body_bottom.getObj("scwin").setReturnValue("clearInterval('" + key + "'" + (force !== "omit" ? ", " + force : "") + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("count 변화 : " + beforeCount + " → " + afterCount + (beforeCount < afterCount ? " (함수 실행됨)" : " (함수 실행 안됨)"));
}
